03-select-country-select.code:
"use client";

import { useState } from 'react';
import { Select, Searchable } from 'ui-lab-components';

const countries = [
  { value: "us", label: "United States", flag: "🇺🇸", code: "+1" },
  { value: "gb", label: "United Kingdom", flag: "🇬🇧", code: "+44" },
  { value: "de", label: "Germany", flag: "🇩🇪", code: "+49" },
  { value: "fr", label: "France", flag: "🇫🇷", code: "+33" },
  { value: "jp", label: "Japan", flag: "🇯🇵", code: "+81" },
  { value: "kr", label: "South Korea", flag: "🇰🇷", code: "+82" },
  { value: "cn", label: "China", flag: "🇨🇳", code: "+86" },
  { value: "in", label: "India", flag: "🇮🇳", code: "+91" },
  { value: "br", label: "Brazil", flag: "🇧🇷", code: "+55" },
  { value: "au", label: "Australia", flag: "🇦🇺", code: "+61" },
  { value: "ca", label: "Canada", flag: "🇨🇦", code: "+1" },
  { value: "mx", label: "Mexico", flag: "🇲🇽", code: "+52" },
];

export default function Example() {
  const [country, setCountry] = useState<string | number | null>("us");
  const selected = countries.find(c => c.value === country);

  return (
    <Select
      selectedKey={country}
      label={selected?.label}
      onSelectionChange={setCountry}
      className="w-72"
    >
      <Select.Trigger>
        <Select.Value
          placeholder="Choose a country..."
          icon={selected && <span className="text-sm">{selected.flag}</span>}
        />
      </Select.Trigger>
      <Searchable.Content searchPlaceholder="Search countries...">
        {countries.map((c) => (
          <Select.Item key={c.value} value={c.value} textValue={c.label} icon={<span className="text-md">{c.flag}</span>}>
            <div className="flex items-center justify-between w-full">
              <span>{c.label}</span>
              <span className="ml-2 text-sm text-foreground-400">{c.code}</span>
            </div>
          </Select.Item>
        ))}
      </Searchable.Content>
    </Select>
  );
}

04-select-chip-multi-pick.code:
"use client";

import { useMemo, useState } from 'react';
import { Badge, Flex, Select, Searchable } from 'ui-lab-components';

const options = [
  { value: 'design', label: 'Design Systems' },
  { value: 'frontend', label: 'Frontend' },
  { value: 'product', label: 'Product' },
  { value: 'docs', label: 'Documentation' },
  { value: 'api', label: 'API' },
  { value: 'qa', label: 'QA' },
  { value: 'ops', label: 'Operations' },
  { value: 'research', label: 'Research' },
];

export default function Example() {
  const [selectedKeys, setSelectedKeys] = useState<Array<string | number>>(['design', 'frontend']);

  const selectedSet = useMemo(() => new Set(selectedKeys), [selectedKeys]);
  const selectedOptions = useMemo(
    () => options.filter((option) => selectedSet.has(option.value)),
    [selectedSet]
  );

  return (
    <Select
      mode="multiple"
      selectedKeys={selectedKeys}
      onSelectionChange={setSelectedKeys}
      className="w-full max-w-xl"
      label={selectedOptions.map((option) => option.label).join(', ')}
    >
      <Select.Trigger>
        <Select.Value>
          {() => (
            <Flex gap="xs" wrap align-center>
              {selectedOptions.length > 0 ? (
                selectedOptions.map((option) => (
                  <Badge
                    key={option.value}
                    dismissible
                    onDismiss={() => setSelectedKeys((prev) => prev.filter((value) => value !== option.value))}
                    pill
                  >
                    {option.label}
                  </Badge>
                ))
              ) : (
                <span className="text-foreground-400">Choose one or more teams</span>
              )}
            </Flex>
          )}
        </Select.Value>
      </Select.Trigger>
      <Searchable.Content searchPlaceholder="Search teams...">
        <Select.List>
          {options.map((option) => (
            <Select.Item
              key={option.value}
              value={option.value}
              textValue={option.label}
              description={selectedSet.has(option.value) ? 'Selected' : 'Click to add to chips'}
            >
              {option.label}
            </Select.Item>
          ))}
        </Select.List>
      </Searchable.Content>
    </Select>
  );
}
